SELECT q.no,q.title,q.image,q.answer,o.option1,o.option2,o.option3,o.option4,q.type,q.theme,q.score
FROM (
	SELECT *
	FROM EXAM_QUESTION


				WHERE no IN(
				    SELECT question_no
				    FROM SCHEDULED_EXAM_MAP
				    WHERE exam_no=#{exam_no}
				)


				WHERE theme=#{theme}
				ORDER BY DBMS_RANDOM.VALUE


	) q
	LEFT JOIN EXAM_OPTION o ON q.no=o.question_no

		WHERE ROWNUM <= #{count}

	ORDER BY q.no

SELECT no,member_id,exam_no,theme,starttime,endtime,totalscore,status
FROM (
	SELECT no,member_id,exam_no,theme,starttime,endtime,totalscore,status
	FROM exam_enrollment
	WHERE member_id=#{member_id}
	  AND exam_no=#{exam_no}
	  AND endtime IS NOT NULL
	ORDER BY endtime DESC
)
WHERE ROWNUM=1

SELECT no,member_id,exam_no,theme,starttime,endtime,totalscore,status
FROM exam_enrollment
WHERE no=#{enrollmentNo}
  AND member_id=#{memberId}

SELECT title
FROM SCHEDULED_EXAM
WHERE no=#{examNo}

SELECT no,title,open_date,close_date,NVL(time_limit,120) AS time_limit,instructor_id
FROM scheduled_exam
WHERE no=#{examNo}

SELECT no, title, answer, score, type
FROM exam_question


		WHERE no IN(
			SELECT question_no
			FROM scheduled_exam_map
			WHERE exam_no=#{exam_no}
		)


		WHERE theme=#{theme}
		  AND no IN

			#{qNo}



ORDER BY no

