INSERT INTO exam_user_answer ( enrollment_no, question_no, user_answer, is_correct, score, grader_id, graded_at ) SELECT sub.* FROM (
SELECT #{item.enrollment_no}, #{item.question_no}, #{item.user_answer, jdbcType=VARCHAR}, #{item.is_correct}, #{item.score}, NULL AS grader_id, NULL AS graded_at FROM DUAL
) sub

